function rectOf(n){return{x:n.x,y:n.y,w:n.w||320,h:n.h||260}}
function intersects(a,b){return a.x<=b.x+b.w&&a.x+a.w>=b.x&&a.y<=b.y+b.h&&a.y+a.h>=b.y}
function bounds(items,padding=0){if(!items.length)return{x:0,y:0,w:1,h:1};const minX=Math.min(...items.map(n=>n.x)),minY=Math.min(...items.map(n=>n.y)),maxX=Math.max(...items.map(n=>n.x+(n.w||320))),maxY=Math.max(...items.map(n=>n.y+(n.h||260)));return{x:minX-padding,y:minY-padding,w:maxX-minX+2*padding,h:maxY-minY+2*padding}}
function bezier(from,to){const x1=from.x+from.w,y1=from.y+from.h/2,x2=to.x,y2=to.y+to.h/2,d=Math.max(70,Math.abs(x2-x1)*.45);return 'M '+x1+' '+y1+' C '+(x1+d)+' '+y1+' '+(x2-d)+' '+y2+' '+x2+' '+y2}
function wouldCycle(edges,from,to){if(from===to)return true;const seen=new Set(),todo=[to];while(todo.length){const id=todo.pop();if(id===from)return true;if(seen.has(id))continue;seen.add(id);for(const e of edges)if(e.from===id)todo.push(e.to)}return false}
function collectInputs(project,targetId){const visited=new Set(),assets=[],texts=[],sourceIds=[],pending=[];function asset(id){if(id&&!assets.includes(id))assets.push(id)}function visit(id){if(visited.has(id))return;visited.add(id);const n=project.nodes.find(n=>n.id===id);if(!n)return;if(id!==targetId&&n.asset){sourceIds.push(id);asset(n.asset);return}if(id!==targetId&&n.type==='task'&&!n.asset){sourceIds.push(id);pending.push(id);return}for(const e of project.edges||[])if(e.to===id)visit(e.from);if(id!==targetId){sourceIds.push(id);if(['note','prompt'].includes(n.type)&&n.prompt)texts.push({id:n.id,title:n.title,text:n.prompt})}for(const ref of n.refs||[])asset(ref)}visit(targetId);return{refs:assets,texts,sourceIds,pending}}
function remapGraph(project,makeId){const nodeMap=new Map(project.nodes.map(n=>[n.id,makeId()])),groupMap=new Map((project.groups||[]).map(g=>[g.id,makeId()]));return{nodes:project.nodes.map(n=>({...n,id:nodeMap.get(n.id),groupId:groupMap.get(n.groupId)||null})),edges:(project.edges||[]).map(e=>({...e,id:makeId(),from:nodeMap.get(e.from),to:nodeMap.get(e.to)})).filter(e=>e.from&&e.to),groups:(project.groups||[]).map(g=>({...g,id:groupMap.get(g.id)}))}}

