const validId=v=>{if(typeof v!=='string'||!/^[a-zA-Z0-9_-]{1,120}$/.test(v))fail('无效 ID');return v};
const text=(v,max=12000)=>{if(typeof v!=='string'||!v.trim()||v.length>max)fail('文本为空或过长');return v.trim()};
const ratios=['16:9','9:16','1:1','3:2','2:3','4:3'];
const position=v=>{if(!Number.isFinite(v)||Math.abs(v)>1000000)fail('位置超出范围');return v};
const size=(v,min=140,max=4000)=>{if(!Number.isFinite(v)||v<min||v>max)fail('尺寸超出范围');return v};
const colors=['sage','blue','rose','amber','violet','gray'];
const color=v=>colors.includes(v)?v:'sage';
function bytesFromBase64(s){if(typeof s!=='string'||s.length>22*1024*1024||!s.length)fail('图片为空或超过 15 MB');let raw;try{raw=atob(s)}catch{fail('图片编码错误')}const a=Uint8Array.from(raw,c=>c.charCodeAt(0));if(a.length>15*1024*1024)fail('图片超过 15 MB');return a}
