function normalizeProject(p){p.nodes??=[];p.edges??=[];p.groups??=[];p.undo??=[];p.redo??=[];p.trash??={};p.updatedAt??=now();for(const n of p.nodes){n.h??=n.type==='note'?200:270;n.w??=320;n.color??='gray'}return p}
export function migrate(board){if(board.version===2){board.projects.forEach(normalizeProject);return board}return{version:2,revision:board.revision||0,projects:[normalizeProject({id:'default',name:'默认项目',nodes:board.nodes||[],createdAt:now()})]}}
