async function update(env,fn){for(let i=0;i<8;i++){const {state,etag}=await load(env),result=fn(state);state.revision++;const written=await env.BUCKET.put('canvas/board.json',JSON.stringify(state),{httpMetadata:{contentType:'application/json'},onlyIf:etag?{etagMatches:etag}:{etagDoesNotMatch:'*'}});if(written)return{state,result}}fail('保存冲突，请重试',409)}
function findProject(state,id='default'){const p=state.projects.find(p=>p.id===validId(id));if(!p)fail('项目不存在或已删除',404);return p}
function findTask(state,id){for(const project of state.projects){const task=project.nodes.find(n=>n.id===id&&n.type==='task');if(task)return{project,task}}fail('任务不存在或已删除',404)}
