function snapshot(p){return structuredClone({nodes:p.nodes,edges:p.edges,groups:p.groups})}
function history(p){p.undo.push(snapshot(p));while(p.undo.length>40||JSON.stringify(p.undo).length>2*1024*1024)p.undo.shift();p.redo=[];p.updatedAt=now()}
function restore(p,s){const runtime=new Map([...Object.values(p.trash),...p.nodes].map(n=>[n.id,n]));const wanted=new Set(s.nodes.map(n=>n.id));for(const n of p.nodes)if(!wanted.has(n.id))p.trash[n.id]=cleanNode(n);const live=new Set(p.nodes.map(n=>n.id));p.nodes=s.nodes.map(old=>{const n=structuredClone(old),r=runtime.get(n.id);if(r&&n.type==='task'){for(const k of ['asset','status','error','completedAt','revisedPrompt','leaseToken','leaseExpiresAt']){if(r[k]!==undefined)n[k]=r[k];else delete n[k]}if(!live.has(n.id)&&n.status==='processing'){n.status='queued';delete n.leaseToken;delete n.leaseExpiresAt}}return n});p.edges=structuredClone(s.edges);p.groups=structuredClone(s.groups);p.updatedAt=now();const entries=Object.entries(p.trash);if(entries.length>1000)p.trash=Object.fromEntries(entries.slice(-1000))}
