const nodePos=a=>({x:position(a.x??0),y:position(a.y??0),w:size(a.w??320),h:size(a.h??270)});
function validateEdge(p,from,to){validId(from);validId(to);if(!p.nodes.some(n=>n.id===from)||!p.nodes.some(n=>n.id===to))fail('连线节点不存在');if(p.edges.some(e=>e.from===from&&e.to===to))fail('这条连线已存在');if(wouldCycle(p.edges,from,to))fail('连线不能形成循环');if(p.edges.length>=1500)fail('连线最多 1500 条')}
function capacity(p,count=1){if(p.nodes.length+count>500)fail('每个项目最多 500 个节点')}
